#include "manager.h"
#include <assert.h>
#include <stdio.h>
int main(void){struct nova_service_manager m;struct nova_managed_service s;nova_service_manager_init(&m);assert(!nova_service_manager_register(0,1));assert(!nova_service_manager_register(&m,0));assert(nova_service_manager_register(&m,1));assert(!nova_service_manager_register(&m,1));assert(!nova_service_manager_publish(&m,1,10,20));assert(!nova_service_manager_begin_start(&m,1,0));assert(nova_service_manager_begin_start(&m,1,10));assert(!nova_service_manager_publish(&m,1,11,20));assert(!nova_service_manager_begin_stop(&m,1,10));assert(nova_service_manager_publish(&m,1,10,20));assert(nova_service_manager_get(&m,1,&s));assert(s.state==NOVA_MANAGED_RUNNING&&s.task_id==10&&s.endpoint==20);assert(!nova_service_manager_begin_stop(&m,1,11));assert(nova_service_manager_begin_stop(&m,1,10));assert(!nova_service_manager_complete_stop(&m,1,11));assert(nova_service_manager_complete_stop(&m,1,10));assert(nova_service_manager_get(&m,1,&s));assert(s.state==NOVA_MANAGED_STOPPED&&!s.task_id&&!s.endpoint);assert(nova_service_manager_begin_start(&m,1,12));assert(nova_service_manager_fail(&m,1,12));assert(nova_service_manager_get(&m,1,&s));assert(s.state==NOVA_MANAGED_FAILED);assert(nova_service_manager_begin_start(&m,1,13));assert(nova_service_manager_publish(&m,1,13,21));assert(nova_service_manager_fail(&m,1,13));assert(!nova_service_manager_get(&m,2,&s));puts("User service manager lifecycle tests passed.");return 0;}
